import { ErrorHandler, NgModule } from '@angular/core';
import { IonicApp, IonicErrorHandler, IonicModule } from 'ionic-angular';

import { MyApp } from './app.component';

import { MODULES, PROVIDERS, DIRECTIVES } from './app.imports';

@NgModule({
    declarations: [

        MyApp

    ],
    imports: [

        MODULES,
        DIRECTIVES,
        IonicModule.forRoot(MyApp, {}, 
{
  links: [
    { loadChildren: '../pages/bag/bag.module#BagPageModule', name: 'BagPage', segment: 'bag', priority: 'low', defaultHistory: [] },
    { loadChildren: '../pages/burgers/burgers.module#BurgersPageModule', name: 'BurgersPage', segment: 'burgers', priority: 'low', defaultHistory: [] },
    { loadChildren: '../pages/intro/intro.module#IntroModule', name: 'IntroComponent', segment: 'intro', priority: 'low', defaultHistory: [] },
    { loadChildren: '../pages/list/list.module#ListModule', name: 'ListComponent', segment: 'list', priority: 'low', defaultHistory: [] },
    { loadChildren: '../pages/login/login.module#LoginPageModule', name: 'LoginPage', segment: 'login', priority: 'low', defaultHistory: [] },
    { loadChildren: '../pages/menu/menu.module#MenuModule', name: 'MenuComponent', segment: 'menu', priority: 'low', defaultHistory: [] },
    { loadChildren: '../pages/menu-item/menu-item.module#MenuItemPageModule', name: 'MenuItemPage', segment: 'menu-item', priority: 'low', defaultHistory: [] },
    { loadChildren: '../pages/ourfood/ourfood.module#OurfoodModule', name: 'OurfoodComponent', segment: 'ourfood', priority: 'low', defaultHistory: [] },
    { loadChildren: '../pages/ourstory/ourstory.module#OurstoryModule', name: 'OurstoryComponent', segment: 'ourstory', priority: 'low', defaultHistory: [] },
    { loadChildren: '../pages/signup/signup.module#SignupPageModule', name: 'SignupPage', segment: 'signup', priority: 'low', defaultHistory: [] },
    { loadChildren: '../pages/tab1/tab1.module#Tab1Module', name: 'Tab1Component', segment: 'tab1', priority: 'low', defaultHistory: [] },
    { loadChildren: '../pages/tab2/tab2.module#Tab2Module', name: 'Tab2Component', segment: 'tab2', priority: 'low', defaultHistory: [] },
    { loadChildren: '../pages/tabs/tabs.module#TabsModule', name: 'TabsComponent', segment: 'tabs', priority: 'low', defaultHistory: [] }
  ]
})

    ],
    bootstrap: [IonicApp],
    entryComponents: [

        MyApp

    ],
    providers: [

        PROVIDERS,
        { provide: ErrorHandler, useClass: IonicErrorHandler },


    ]
})
export class AppModule { }



